        (s_axis_psum_stream_TVALID && s_axis_psum_stream_TREADY);

    always_ff @(posedge ap_clk) begin
        if (!ap_rst_n) begin
            overlap_weight_reads  <= 0;
            overlap_compute_beats <= 0;
            overlap_drain_beats   <= 0;
            overlap_weight_compute <= 0;
            overlap_weight_drain  <= 0;
        end else if (overlap_monitor_active) begin
            if (monitor_weight_read_hs) overlap_weight_reads <= overlap_weight_reads + 1;
            if (monitor_compute_hs) overlap_compute_beats <= overlap_compute_beats + 1;
            if (monitor_drain_hs) overlap_drain_beats <= overlap_drain_beats + 1;
            if (monitor_weight_read_hs && monitor_compute_hs) overlap_weight_compute <= overlap_weight_compute + 1;
            if (monitor_weight_read_hs && monitor_drain_hs) overlap_weight_drain <= overlap_weight_drain + 1;
        end
    end

    function automatic integer align_up(input integer value, input integer align);
        begin
            align_up = ((value + align - 1) / align) * align;
        end
    endfunction

    function automatic integer div_ceil(input integer value, input integer divisor);
        begin
            div_ceil = (value + divisor - 1) / divisor;
        end
    endfunction

    function automatic integer act_value(input integer m, input integer k);
        begin
            act_value = ((m * 5 + k * 3) % 13) - 6;
        end
    endfunction

    function automatic integer act_exp_value(input integer m, input integer g, input bit varied);
        begin
            act_exp_value = varied ? (((m + g * 3) % 3) - 1) : 0;
        end
    endfunction

    function automatic integer weight_value(input integer seed, input integer k, input integer n);
        begin
            weight_value = ((seed + k * 7 + n * 5) % 11) - 5;
        end
    endfunction

    function automatic longint signed bias_value(input integer seed, input integer n);
        begin
            bias_value = ((((seed + n * 3) % 9) - 4) <<< (OUT_FRAC - 4));
        end
    endfunction

    function automatic longint signed sat_ref(input logic signed [127:0] v);
        logic signed [127:0] max_v;
        logic signed [127:0] min_v;
        begin
            max_v = (128'sd1 <<< (OUT_ACC_BITS - 1)) - 1;
            min_v = -(128'sd1 <<< (OUT_ACC_BITS - 1));
            if (v > max_v) sat_ref = $signed(max_v[63:0]);
            else if (v < min_v) sat_ref = $signed(min_v[63:0]);
            else sat_ref = $signed(v[63:0]);
        end
    endfunction

    function automatic longint signed round_shift_ref(input logic signed [127:0] v, input integer shift);
        logic signed [127:0] half;
        begin
            if (shift <= 0) begin
                round_shift_ref = sat_ref(v);
            end else begin
                half = 128'sd1 <<< (shift - 1);
                if (v >= 0) begin
                    round_shift_ref = sat_ref((v + half) >>> shift);
                end else begin
                    round_shift_ref = sat_ref(-(((-v) + half) >>> shift));
                end
            end
        end
    endfunction

    function automatic longint signed sat_q32_ref(input logic signed [127:0] v);
        logic signed [127:0] max_v;
        logic signed [127:0] min_v;
        begin
            max_v = (128'sd1 <<< 47) - 1;
            min_v = -(128'sd1 <<< 47);
            if (v > max_v) sat_q32_ref = $signed(max_v[63:0]);
            else if (v < min_v) sat_q32_ref = $signed(min_v[63:0]);
            else sat_q32_ref = $signed(v[63:0]);
        end
    endfunction

    function automatic longint signed round_shift_q32_ref(input logic signed [127:0] v, input integer shift);
        logic signed [127:0] half;
        begin
            if (shift <= 0) begin
                round_shift_q32_ref = sat_q32_ref(v);
            end else begin
                half = 128'sd1 <<< (shift - 1);
                if (v >= 0) begin
                    round_shift_q32_ref = sat_q32_ref((v + half) >>> shift);
                end else begin
                    round_shift_q32_ref = sat_q32_ref(-(((-v) + half) >>> shift));
                end
            end
        end
    endfunction

    function automatic longint signed sat_add_ref(input longint signed a, input longint signed b);
        logic signed [127:0] wide;
        begin
            wide = a;
            wide = wide + b;
            sat_add_ref = sat_ref(wide);
        end
    endfunction

    function automatic longint signed shift_apply(input integer x, input integer e);
        integer shift;
        integer rs;
        logic signed [127:0] wide;
        begin
            shift = e + OUT_FRAC;
            wide = x;
            if (shift >= 0) begin
                wide = wide <<< shift;
                shift_apply = sat_ref(wide);
            end else begin
                rs = -shift;
                if (rs >= 127) shift_apply = 0;
                else shift_apply = round_shift_ref(wide, rs);
            end
        end
    endfunction

    function automatic longint signed fixed_from_i32(input integer x);
        logic signed [127:0] wide;
        begin
            wide = x;
            fixed_from_i32 = sat_ref(wide <<< OUT_FRAC);
        end
    endfunction

    function automatic longint signed fixed_mul_div(input longint signed a, input longint signed b, input integer divisor);
        logic signed [127:0] value;
        logic signed [127:0] recip;
        begin
            value = a;
            value = value * b;
            recip = (divisor == 3) ? 128'sd5592405 : 128'sd2796203;
            value = value * recip;
            fixed_mul_div = sat_ref(value >>> (OUT_FRAC + 24));
        end
    endfunction

    function automatic longint signed hard_silu(input longint signed x);
        longint signed gate;
        begin
            gate = sat_add_ref(x, fixed_from_i32(3));
            if (gate < 0) gate = 0;
            if (gate > fixed_from_i32(6)) gate = fixed_from_i32(6);
            hard_silu = fixed_mul_div(x, gate, 6);
        end
    endfunction

    function automatic longint signed hard_gelu(input longint signed x);
        longint signed gate;
        begin
            gate = sat_add_ref(x, fixed_from_i32(3) >>> 1);
            if (gate < 0) gate = 0;
            if (gate > fixed_from_i32(3)) gate = fixed_from_i32(3);
            hard_gelu = fixed_mul_div(x, gate, 3);
        end
    endfunction

