                123: gelu_lut_slope_q16 = 64'sd67108890;
                124: gelu_lut_slope_q16 = 64'sd67108879;
                125: gelu_lut_slope_q16 = 64'sd67108873;
                126: gelu_lut_slope_q16 = 64'sd67108870;
                127: gelu_lut_slope_q16 = 64'sd67108867;
                default: gelu_lut_slope_q16 = 64'sd0;
            endcase
        end
    endfunction

    function automatic longint signed gelu_lut128_q32(input longint signed x_q22);
        longint signed min_x;
        longint signed max_x;
        longint signed step;
        longint signed rel;
        integer idx;
        longint signed rem;
        logic signed [127:0] interp;
        begin
            min_x = -(64'sd6 <<< OUT_FRAC);
            max_x =  (64'sd6 <<< OUT_FRAC);
            step = (64'sd12 <<< OUT_FRAC) / 128;
            if (x_q22 <= min_x) begin
                gelu_lut128_q32 = 0;
            end else if (x_q22 >= max_x) begin
                gelu_lut128_q32 = sat_q32_ref(x_q22 <<< (32 - OUT_FRAC));
            end else begin
                rel = x_q22 - min_x;
                idx = rel / step;
                if (idx < 0) idx = 0;
                if (idx > 127) idx = 127;
                rem = rel - idx * step;
                interp = gelu_lut_slope_q16(idx);
                interp = interp * rem;
                gelu_lut128_q32 = sat_q32_ref(gelu_lut_y0_q32(idx) + round_shift_q32_ref(interp, 16));
            end
        end
    endfunction

    function automatic longint signed round_mul_q22(input longint signed a, input longint signed b);
        logic signed [127:0] p;
        begin
            p = a;
            p = p * b;
            round_mul_q22 = round_shift_ref(p, OUT_FRAC);
        end
    endfunction

    function automatic integer choose_pot_exp_q22(input longint signed max_abs);
        integer selected_shift;
        integer shift;
        bit found;
        bit fits;
        logic signed [127:0] scaled;
        begin
            if (max_abs <= 0) begin
                choose_pot_exp_q22 = 0;
            end else begin
                selected_shift = OUT_FRAC;
                found = 1'b0;
                for (shift = -20; shift <= 62; shift = shift + 1) begin
                    if (shift >= 0) begin
                        fits = (max_abs <= (128'sd127 <<< shift));
                    end else begin
                        scaled = max_abs;
                        scaled = scaled <<< (-shift);
                        fits = (scaled <= 127);
                    end
                    if (fits && !found) begin
                        selected_shift = shift;
                        found = 1'b1;
                    end
                end
                choose_pot_exp_q22 = selected_shift - OUT_FRAC;
                if (choose_pot_exp_q22 < -30) choose_pot_exp_q22 = -30;
                if (choose_pot_exp_q22 > 30) choose_pot_exp_q22 = 30;
            end
        end
    endfunction

    function automatic integer quantize_q22_exp(input longint signed x, input integer exp);
        integer shift;
        longint signed q;
        logic signed [127:0] wide;
        begin
            shift = exp + OUT_FRAC;
            if (shift >= 0) begin
                q = round_shift_ref(x, shift);
            end else begin
                wide = x;
                wide = wide <<< (-shift);
                q = sat_ref(wide);
            end
            if (q > 127) q = 127;
            if (q < -127) q = -127;
            quantize_q22_exp = q;
        end
    endfunction

    function automatic integer choose_pot_exp_q32(input longint signed max_abs);
        integer selected_shift;
        integer shift;
        bit found;
        bit fits;
        logic signed [127:0] scaled;
        begin
            if (max_abs <= 0) begin
                choose_pot_exp_q32 = 0;
            end else begin
                selected_shift = 32;
                found = 1'b0;
                for (shift = -20; shift <= 62; shift = shift + 1) begin
                    if (shift >= 0) begin
                        fits = (max_abs <= (128'sd127 <<< shift));
                    end else begin
                        scaled = max_abs;
                        scaled = scaled <<< (-shift);
                        fits = (scaled <= 127);
                    end
                    if (fits && !found) begin
                        selected_shift = shift;
                        found = 1'b1;
                    end
                end
                choose_pot_exp_q32 = selected_shift - 32;
                if (choose_pot_exp_q32 < -30) choose_pot_exp_q32 = -30;
                if (choose_pot_exp_q32 > 30) choose_pot_exp_q32 = 30;
            end
        end
    endfunction

    function automatic integer quantize_q32_exp(input longint signed x, input integer exp);
        integer shift;
        longint signed q;
        logic signed [127:0] wide;
        begin
            shift = exp + 32;
            if (shift >= 0) begin
                q = round_shift_ref(x, shift);
            end else begin
                wide = x;
                wide = wide <<< (-shift);
                q = sat_ref(wide);
            end
            if (q > 127) q = 127;
            if (q < -127) q = -127;
            quantize_q32_exp = q;
        end
    endfunction

    function automatic longint signed r_i64_out(input integer addr);
        logic [63:0] v;
        begin
            v = {mem_out[addr + 7], mem_out[addr + 6], mem_out[addr + 5], mem_out[addr + 4],
                 mem_out[addr + 3], mem_out[addr + 2], mem_out[addr + 1], mem_out[addr + 0]};
            r_i64_out = $signed(v);
        end
    endfunction

    function automatic integer r_i32_out(input integer addr);
        logic [31:0] v;
        begin
            v = {mem_out[addr + 3], mem_out[addr + 2], mem_out[addr + 1], mem_out[addr + 0]};
            r_i32_out = $signed(v);
        end
    endfunction

    function automatic integer sat_i32_ref(input longint signed v);
        begin
            if (v > 2147483647) sat_i32_ref = 2147483647;
            else if (v < (-2147483647 - 1)) sat_i32_ref = (-2147483647 - 1);
            else sat_i32_ref = $signed(v[31:0]);
        end
    endfunction

    task automatic clear_memories;
        integer i;
        begin
            for (i = 0; i < MEM_BYTES; i = i + 1) begin
                mem_w0[i] = 8'd0;
                mem_w1[i] = 8'd0;
                mem_act[i] = 8'd0;
                mem_out[i] = 8'd0;
            end
        end
    endtask

    task automatic wb_act(input integer off, input integer value);
        begin
            if (off >= 0 && off < MEM_BYTES) mem_act[off] = value[7:0];
        end
    endtask

    task automatic wb_weight(input integer port, input integer off, input integer value);
        begin
            if (off >= 0 && off < MEM_BYTES) begin
                if (port == 0) mem_w0[off] = value[7:0];
                else           mem_w1[off] = value[7:0];
            end
        end
    endtask

    task automatic wr32(input integer off, input [31:0] value);
        begin
            wb_act(off + 0, value[7:0]);
            wb_act(off + 1, value[15:8]);
            wb_act(off + 2, value[23:16]);
            wb_act(off + 3, value[31:24]);
        end
    endtask

    task automatic wr64(input integer off, input [63:0] value);
        begin
            wr32(off, value[31:0]);
            wr32(off + 4, value[63:32]);
        end
    endtask

    task automatic wb_i64_act(input integer off, input longint signed value);
        integer i;
        logic [63:0] raw;
        begin
            raw = value[63:0];
            for (i = 0; i < 8; i = i + 1) begin
                wb_act(off + i, raw[i * 8 +: 8]);
            end
        end
    endtask

    task automatic fill_biases(input integer up_off, input integer up_cols, input integer up_seed,
                               input integer down_off, input integer down_cols, input integer down_seed);
        integer i;
        begin
            for (i = 0; i < up_cols; i = i + 1)
                wb_i64_act(up_off + i * OUT_BYTES, bias_value(up_seed, i));
            for (i = 0; i < down_cols; i = i + 1)
                wb_i64_act(down_off + i * OUT_BYTES, bias_value(down_seed, i));
        end
    endtask

    task automatic fill_act(input integer q_off, input integer s_off,
                            input integer rows, input integer K,
                            input integer row_stride, input integer scale_stride,
                            input bit varied_exp);
        integer m;
        integer k;
        integer g;
        integer groups;
        begin
            groups = K / GROUP;
            for (m = 0; m < rows; m = m + 1) begin
                for (k = 0; k < K; k = k + 1)
                    wb_act(q_off + m * row_stride + k, act_value(m, k));
                for (g = 0; g < groups; g = g + 1)
                    wb_act(s_off + m * scale_stride + g, act_exp_value(m, g, varied_exp));
            end
        end
    endtask

    task automatic pack_weight_ports_exp(input integer q0_off, input integer q1_off,
                                         input integer s0_off, input integer s1_off,
                                         input integer seed, input integer K, input integer N,
                                         input integer nt_stride_q, input integer nt_stride_s,
                                         input integer e0);
        integer k_tiles;
        integer n_tiles;
        integer nt;
        integer kt;
        integer lane;
        integer kw;
        integer b;
        integer word_off_bytes;
        integer k_in_tile;
        integer k_abs;
        integer n0;
        integer n1;
        integer q0_kt;
        integer q1_kt;
        integer s0_kt;
        integer s1_kt;
        integer byte_off;
        begin
            k_tiles = div_ceil(K, TILE_K);
            n_tiles = div_ceil(N, SA_N);
            for (nt = 0; nt < n_tiles; nt = nt + 1) begin
                for (kt = 0; kt < k_tiles; kt = kt + 1) begin
                    q0_kt = q0_off + nt * nt_stride_q + kt * WEIGHT_WORDS_PER_KTILE_PER_PORT * AXI_BYTES;
                    q1_kt = q1_off + nt * nt_stride_q + kt * WEIGHT_WORDS_PER_KTILE_PER_PORT * AXI_BYTES;
                    s0_kt = s0_off + nt * nt_stride_s + kt * SCALE_WORDS_PER_KTILE_PER_PORT * AXI_BYTES;
                    s1_kt = s1_off + nt * nt_stride_s + kt * SCALE_WORDS_PER_KTILE_PER_PORT * AXI_BYTES;
                    for (kw = 0; kw < TILE_K; kw = kw + 1) begin
                        word_off_bytes = kw * WEIGHT_WORDS_PER_K_PER_PORT * AXI_BYTES;
                        for (lane = 0; lane < WEIGHT_COLS_PER_PORT; lane = lane + 1) begin
                            k_in_tile = kw;
                            k_abs = kt * TILE_K + k_in_tile;
                            n0 = nt * SA_N + lane;
                            n1 = nt * SA_N + WEIGHT_COLS_PER_PORT + lane;
                            wb_weight(0, q0_kt + word_off_bytes + lane,
                                      (k_abs < K && n0 < N) ? weight_value(seed, k_abs, n0) : 0);
                            wb_weight(1, q1_kt + word_off_bytes + lane,
                                      (k_abs < K && n1 < N) ? weight_value(seed, k_abs, n1) : 0);
                        end
                    end
                    for (lane = 0; lane < WEIGHT_COLS_PER_PORT; lane = lane + 1) begin
                        for (b = 0; b < GROUPS_PER_KTILE; b = b + 1) begin
                            byte_off = lane * GROUPS_PER_KTILE + b;
                            wb_weight(0, s0_kt + byte_off, e0);
                            wb_weight(1, s1_kt + byte_off, e0);
                        end
                    end
`ifdef V6_SYSTEM_TB_KEEP_OLD_PACK_FOR_DEBUG
                    for (lane = 0; lane < WEIGHT_COLS_PER_PORT; lane = lane + 1) begin
                        for (kw = 0; kw < TILE_K / AXI_BYTES; kw = kw + 1) begin
                            word_off_bytes = (lane * (TILE_K / AXI_BYTES) + kw) * AXI_BYTES;
                            for (b = 0; b < AXI_BYTES; b = b + 1) begin
                                k_in_tile = kw * AXI_BYTES + b;
                                k_abs = kt * TILE_K + k_in_tile;
                                n0 = nt * SA_N + lane;
                                n1 = nt * SA_N + WEIGHT_COLS_PER_PORT + lane;
                                wb_weight(0, q0_kt + word_off_bytes + b,
                                          (k_abs < K && n0 < N) ? weight_value(seed, k_abs, n0) : 0);
                                wb_weight(1, q1_kt + word_off_bytes + b,
                                          (k_abs < K && n1 < N) ? weight_value(seed, k_abs, n1) : 0);
                            end
                        end
                        for (b = 0; b < GROUPS_PER_KTILE; b = b + 1) begin
                            byte_off = (lane * GROUPS_PER_KTILE + b) * 2;
                            wb_weight(0, s0_kt + byte_off + 0, e0);
                            wb_weight(0, s0_kt + byte_off + 1, DISABLED_EXP);
                            wb_weight(1, s1_kt + byte_off + 0, e0);
                            wb_weight(1, s1_kt + byte_off + 1, DISABLED_EXP);
                        end
                    end
`endif
                end
            end
        end
    endtask

    task automatic pack_weight_ports(input integer q0_off, input integer q1_off,
                                     input integer s0_off, input integer s1_off,
                                     input integer seed, input integer K, input integer N,
                                     input integer nt_stride_q, input integer nt_stride_s);
        begin
            pack_weight_ports_exp(q0_off, q1_off, s0_off, s1_off,
                                  seed, K, N, nt_stride_q, nt_stride_s, 0);
        end
    endtask

