                                   input integer nt_q_stride,
                                   input integer nt_s_stride);
        begin
            wr32(0,  32'h384d4c56);
            wr32(4,  32'd15);
            wr32(8,  32'd64);
            wr32(12, 32'd32);
            wr64(16, act_q);
            wr64(24, act_s);
            wr32(32, act_row_stride);
            wr32(36, 32'd1);
            wr32(40, K);
            wr32(44, 32'd0);
            wr64(48, 64'd0);
            wr32(56, N); wr32(60, 32'd0); wr32(64, 32'd0);
            wr32(68, 32'd0);
            wr64(72, w_q0); wr64(80, w_q1);
            wr64(120, w_s0); wr64(128, w_s1);
            wr64(168, dst);
            wr64(192, 64'd0);
            wr32(216, out_stride);
            wr32(228, nt_q_stride);
            wr32(232, nt_s_stride);
            wr32(236, act_scale_stride);
