    task automatic init_liveness_task(input [31:0] task_type);
        integer output_count;
        begin
            clear_memories();
            output_count = (task_type == 32'd65) ? 3 : 1;

            wr32(0,  32'h384d4c56);
            wr32(4,  32'd15);
            wr32(8,  task_type);
            wr32(12, 32'd32);
            wr64(16, 64'd4096);
            wr64(24, 64'd8192);
            wr32(32, 32'd128);
            wr32(36, output_count);
            wr32(40, 32'd128);
            wr32(44, (task_type == 32'd67 || task_type == 32'd68) ? 32'd1 : 32'd0);
            wr64(48, 64'd0);
            wr32(56, 32'd32); wr32(60, 32'd32); wr32(64, 32'd32);
            wr32(68, 32'd0);
            wr64(192, 64'd0); wr64(200, 64'd0); wr64(208, 64'd0);
            wr32(216, 32'd256); wr32(220, 32'd256); wr32(224, 32'd256);
            wr32(228, 32'd2048);
            wr32(232, 32'd128);
            wr32(236, 32'd16);
            wr32(344, 32'd128);
            wr32(348, 32'd128);
