    task automatic ctrl_write(input [6:0] addr, input [31:0] data);
        bit aw_done;
        bit w_done;
        begin
            aw_done = 1'b0;
            w_done = 1'b0;
            @(negedge ap_clk);
            s_axi_control_AWADDR  = addr;
            s_axi_control_AWVALID = 1'b1;
            s_axi_control_WDATA   = data;
            s_axi_control_WSTRB   = 4'hf;
            s_axi_control_WVALID  = 1'b1;
            s_axi_control_BREADY  = 1'b1;
            while (!(aw_done && w_done)) begin
                @(posedge ap_clk);
                if (s_axi_control_AWREADY) begin
                    aw_done = 1'b1;
                    s_axi_control_AWVALID = 1'b0;
                end
                if (s_axi_control_WREADY) begin
                    w_done = 1'b1;
                    s_axi_control_WVALID = 1'b0;
                end
            end
            while (!s_axi_control_BVALID) @(posedge ap_clk);
            @(negedge ap_clk);
            s_axi_control_BREADY  = 1'b0;
        end
    endtask

    task automatic ctrl_read(input [6:0] addr, output [31:0] data);
        begin
            @(negedge ap_clk);
            s_axi_control_ARADDR  = addr;
            s_axi_control_ARVALID = 1'b1;
            s_axi_control_RREADY  = 1'b1;
            while (!s_axi_control_ARREADY) @(posedge ap_clk);
            @(negedge ap_clk);
            s_axi_control_ARVALID = 1'b0;
            while (!s_axi_control_RVALID) @(posedge ap_clk);
            data = s_axi_control_RDATA;
            @(negedge ap_clk);
            s_axi_control_RREADY  = 1'b0;
        end
    endtask

    task automatic reset_dut;
        begin
            ap_rst_n = 1'b0;
            overlap_monitor_active = 1'b0;
            s_axi_control_AWVALID = 1'b0;
            s_axi_control_AWADDR  = '0;
            s_axi_control_WVALID  = 1'b0;
            s_axi_control_WDATA   = '0;
            s_axi_control_WSTRB   = 4'h0;
            s_axi_control_BREADY  = 1'b0;
            s_axi_control_ARVALID = 1'b0;
            s_axi_control_ARADDR  = '0;
            s_axi_control_RREADY  = 1'b0;
            repeat (20) @(posedge ap_clk);
            ap_rst_n = 1'b1;
            repeat (10) @(posedge ap_clk);
        end
    endtask

    task automatic reset_overlap_monitor;
        begin
            @(negedge ap_clk);
            overlap_monitor_active = 1'b0;
            overlap_weight_reads = 0;
            overlap_compute_beats = 0;
            overlap_drain_beats = 0;
            overlap_weight_compute = 0;
            overlap_weight_drain = 0;
        end
    endtask

    task automatic start_overlap_monitor;
        begin
            @(negedge ap_clk);
            overlap_monitor_active = 1'b1;
        end
    endtask

    task automatic check_overlap_monitor(input string name);
        begin
            @(negedge ap_clk);
            overlap_monitor_active = 1'b0;
            $display("[SYS] OVERLAP %s weight_reads=%0d compute_beats=%0d drain_beats=%0d weight_compute=%0d weight_drain=%0d",
                     name, overlap_weight_reads, overlap_compute_beats, overlap_drain_beats,
                     overlap_weight_compute, overlap_weight_drain);
            if (overlap_weight_reads <= 0 || overlap_compute_beats <= 0 || overlap_drain_beats <= 0) begin
                $fatal(1, "[SYS] FAIL %s overlap monitor saw no weight/compute/drain activity", name);
            end
            if (overlap_weight_compute <= 0) begin
                $fatal(1, "[SYS] FAIL %s weight load not hidden by compute", name);
            end
            if (name == "REAL_VISION_DENSE_K768" && overlap_weight_compute < 2000) begin
                $fatal(1, "[SYS] FAIL %s insufficient weight/compute overlap: %0d < 2000",
                       name, overlap_weight_compute);
            end
        end
    endtask

    task automatic program_and_start;
        begin
            ctrl_write(7'h10, 32'd0);
            ctrl_write(7'h14, 32'd0);
            ctrl_write(7'h1c, 32'd0);
            ctrl_write(7'h20, 32'd0);
            ctrl_write(7'h28, 32'd0);
            ctrl_write(7'h2c, 32'd0);
            ctrl_write(7'h34, 32'd0);
            ctrl_write(7'h38, 32'd0);
            ctrl_write(7'h40, 32'd0);
            ctrl_write(7'h44, 32'd0);
            ctrl_write(7'h00, 32'd1);
        end
    endtask

    task automatic wait_done(input string name);
        integer cycle;
        reg [31:0] ap_ctrl;
        begin
            for (cycle = 0; cycle < WATCHDOG_CYCLES; cycle = cycle + 1) begin
                ctrl_read(7'h00, ap_ctrl);
                if (ap_ctrl[1]) begin
                    $display("[SYS] DONE %s cycles=%0d AP_CTRL=0x%08x", name, cycle, ap_ctrl);
                    return;
                end
                if ((cycle != 0) && ((cycle % 100000) == 0)) begin
                    $display("[SYS] WAIT %s cycles=%0d AP_CTRL=0x%08x AXI act_ar=%0b/%0b act_r=%0b/%0b w0_ar=%0b/%0b w0_r=%0b/%0b w1_ar=%0b/%0b w1_r=%0b/%0b out_aw=%0b/%0b out_w=%0b/%0b out_b=%0b/%0b AXIS a=%0b/%0b w0=%0b/%0b w1=%0b/%0b c=%0b/%0b psum=%0b/%0b PE pending=%0b drain=%0b row=%0d seg=%0d",
                             name, cycle, ap_ctrl,
                             m_axi_gmem_act_ARVALID, m_axi_gmem_act_ARREADY,
                             m_axi_gmem_act_RVALID,  m_axi_gmem_act_RREADY,
                             m_axi_gmem_w0_ARVALID,  m_axi_gmem_w0_ARREADY,
                             m_axi_gmem_w0_RVALID,   m_axi_gmem_w0_RREADY,
                             m_axi_gmem_w1_ARVALID,  m_axi_gmem_w1_ARREADY,
                             m_axi_gmem_w1_RVALID,   m_axi_gmem_w1_RREADY,
                             m_axi_gmem_out_AWVALID, m_axi_gmem_out_AWREADY,
                             m_axi_gmem_out_WVALID,  m_axi_gmem_out_WREADY,
                             m_axi_gmem_out_BVALID,  m_axi_gmem_out_BREADY,
                             m_axis_a_stream_TVALID,    m_axis_a_stream_TREADY,
                             m_axis_w0_stream_TVALID,   m_axis_w0_stream_TREADY,
                             m_axis_w1_stream_TVALID,   m_axis_w1_stream_TREADY,
                             m_axis_ctrl_stream_TVALID, m_axis_ctrl_stream_TREADY,
                             s_axis_psum_stream_TVALID, s_axis_psum_stream_TREADY,
                             pe_array.pending_valid, pe_array.drain_phase_active,
                             pe_array.drain_row_idx, pe_array.drain_seg_idx);
                end
                repeat (8) @(posedge ap_clk);
            end
            $fatal(1, "[SYS] TIMEOUT %s last_AP_CTRL=0x%08x", name, ap_ctrl);
        end
    endtask

    task automatic run_liveness_case(input [31:0] task_type, input string name);
        begin
            $display("[SYS] START liveness %s task_type=%0d", name, task_type);
            reset_dut();
            init_liveness_task(task_type);
            program_and_start();
            wait_done(name);
        end
    endtask

    task automatic compare_dense_k768(input string name);
        integer m;
        integer n;
        integer kt;
        integer k;
        integer part;
        longint signed total;
        integer hw;
        longint signed expected;
        integer err;
        begin
            err = 0;
            for (m = 0; m < 32; m = m + 1) begin
                for (n = 0; n < 32; n = n + 1) begin
                    total = 0;
                    for (kt = 0; kt < div_ceil(768, GROUP); kt = kt + 1) begin
                        part = 0;
                        for (k = kt * GROUP; k < (kt + 1) * GROUP; k = k + 1)
                            part = part + act_value(m, k) * weight_value(165, k, n);
                        total = sat_add_ref(total, shift_apply(part, act_exp_value(m, kt, 1'b1)));
                    end
                    hw = r_i32_out(m * 128 + n * DENSE_OUT_BYTES);
                    expected = sat_i32_ref(total);
                    if (hw != expected) begin
                        if (err < 8) $display("[SYS] %s mismatch row=%0d col=%0d hw=%0d expected=%0d", name, m, n, hw, expected);
                        err = err + 1;
                    end
                end
            end
            if (err != 0) $fatal(1, "[SYS] FAIL %s mismatches=%0d", name, err);
            $display("[SYS] PASS %s numeric", name);
        end
    endtask

    task automatic run_numeric_dense_k768;
        integer K;
        integer N;
        integer kt;
        integer nt_q_stride;
        integer nt_s_stride;
        begin
            K = 768;
            N = 32;
            kt = 6;
            nt_q_stride = WEIGHT_WORDS_PER_KTILE_PER_PORT * AXI_BYTES * kt;
            nt_s_stride = SCALE_WORDS_PER_KTILE_PER_PORT * AXI_BYTES * kt;
            $display("[SYS] START numeric REAL_VISION_DENSE_K768");
            reset_dut();
            clear_memories();
            fill_act(4096, 65536, 32, K, 768, 32, 1'b1);
            pack_weight_ports(0, 0, nt_q_stride, nt_q_stride, 165, K, N, nt_q_stride, nt_s_stride);
            init_dense_task(K, N, 4096, 65536, 768, 32,
                            0, 0, nt_q_stride, nt_q_stride,
                            0, 128, nt_q_stride, nt_s_stride);
            reset_overlap_monitor();
            start_overlap_monitor();
            program_and_start();
            wait_done("REAL_VISION_DENSE_K768");
            check_overlap_monitor("REAL_VISION_DENSE_K768");
            compare_dense_k768("REAL_VISION_DENSE_K768");
        end
    endtask

    task automatic run_numeric_dense_bias_only;
        integer K;
        integer N;
        integer act_scale_stride;
        integer out_stride;
        integer bias_off;
        integer m;
        integer n;
        integer hw;
        longint signed ref_v;
        integer err;
        begin
            K = 128;
            N = 128;
            act_scale_stride = ((div_ceil(K, GROUP) + 15) / 16) * 16;
            out_stride = N * DENSE_OUT_BYTES;
            bias_off = 131072;

            $display("[SYS] START numeric DENSE_BIAS_ONLY_K128_N128");
            reset_dut();
            clear_memories();
            fill_act(4096, 65536, 32, K, K, act_scale_stride, 1'b0);
            for (n = 0; n < N; n = n + 1)
                wb_i64_act(bias_off + n * OUT_BYTES, bias_value(167, n));
            init_dense_task(K, N,
                            4096, 65536, K, act_scale_stride,
                            0, 0, 0, 0,
                            0, out_stride,
                            WEIGHT_WORDS_PER_KTILE_PER_PORT * AXI_BYTES,
                            SCALE_WORDS_PER_KTILE_PER_PORT * AXI_BYTES);
            wr64(192, bias_off);
            program_and_start();
            wait_done("DENSE_BIAS_ONLY_K128_N128");

            err = 0;
            for (m = 0; m < 32; m = m + 1) begin
                for (n = 0; n < N; n = n + 1) begin
                    ref_v = bias_value(167, n);
                    hw = r_i32_out(m * out_stride + n * DENSE_OUT_BYTES);
                    if (hw != sat_i32_ref(ref_v)) begin
                        if (err < 8) $display("[SYS] DENSE_BIAS_ONLY_K128_N128 mismatch row=%0d col=%0d hw=%0d ref=%0d",
                                              m, n, hw, sat_i32_ref(ref_v));
                        err = err + 1;
                    end
                end
            end
            if (err != 0) $fatal(1, "[SYS] FAIL DENSE_BIAS_ONLY_K128_N128 mismatches=%0d", err);
            $display("[SYS] PASS DENSE_BIAS_ONLY_K128_N128 numeric");
        end
    endtask

    task automatic compare_qkv_tail(input string name);
        integer rows;
        integer out_stride;
        integer dst_base [0:2];
        integer seed [0:2];
        integer o;
        integer m;
        integer n;
        integer k;
        integer kt;
        longint signed total;
        integer hw;
        integer err;
        begin
            rows = 46;
            out_stride = 128;
            dst_base[0] = 0;
            dst_base[1] = rows * out_stride;
            dst_base[2] = rows * out_stride * 2;
            seed[0] = 201;
            seed[1] = 224;
            seed[2] = 247;
            err = 0;
            for (o = 0; o < 3; o = o + 1) begin
                for (m = 0; m < rows; m = m + 1) begin
                    for (n = 0; n < 32; n = n + 1) begin
                        total = 0;
                        for (kt = 0; kt < div_ceil(128, GROUP); kt = kt + 1) begin
                            integer part;
                            part = 0;
                            for (k = kt * GROUP; k < (kt + 1) * GROUP; k = k + 1) begin
                                part = part + act_value(m, k) * weight_value(seed[o], k, n);
                            end
                            total = sat_add_ref(total, shift_apply(part, 0));
                        end
                        hw = r_i32_out(dst_base[o] + m * out_stride + n * DENSE_OUT_BYTES);
                        if (hw != sat_i32_ref(total)) begin
                            if (err < 8) $display("[SYS] %s mismatch out=%0d row=%0d col=%0d hw=%0d ref=%0d", name, o, m, n, hw, total);
                            err = err + 1;
                        end
                    end
                end
            end
            if (err != 0) $fatal(1, "[SYS] FAIL %s mismatches=%0d", name, err);
            $display("[SYS] PASS %s numeric", name);
        end
    endtask

