            pack_weight_ports(q0_1, q0_1, s0_1, s0_1, 224, K, 32, nt_q_stride, nt_s_stride);
            pack_weight_ports(q0_2, q0_2, s0_2, s0_2, 247, K, 32, nt_q_stride, nt_s_stride);
